#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
cd "$(dirname "$0")/.."
REPO="$PWD"
IDENTITY="Developer ID Application: Christian Stephens (H45U5SB635)"
TEAM_ID="H45U5SB635"
PROFILE="dahlia-notary"
KEY_FILE="scripts/sparkle-public-key.txt"
BACKUP="$HOME/dahlia-sparkle-private-key"

banner "Dahlia release setup (one time)"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Check out main"
say "Releases are built from a clean, up-to-date main in $REPO."
git fetch -q origin
branch=$(git branch --show-current)
if [[ -n "$(git status --porcelain)" ]]; then
  warn "This folder has uncommitted changes. Commit or move them, then run this again."
  git status --short | head -20
  exit 1
fi
if [[ "$branch" != "main" ]]; then
  say "This folder is on branch '$branch'."
  confirm "Switch it to main?" || { warn "Setup needs main. Stopping."; exit 1; }
  git switch -q main
fi
git merge -q --ff-only origin/main
printf '  %s✓%s on main at %s\n' "$GREEN" "$RESET" "$(git log --oneline -1)"
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Developer ID certificate"
until security find-identity -v -p codesigning | grep -qF "\"$IDENTITY\""; do
  warn "The keychain has no \"$IDENTITY\"."
  open_url "https://developer.apple.com/account/resources/certificates/list"
  step "Download your Developer ID Application certificate (create one with + if none exists)."
  step "Double-click the downloaded .cer so Keychain Access installs it in your login keychain."
  pause "Press Enter when it's installed to check again."
done
printf '  %s✓%s found %s\n' "$GREEN" "$RESET" "$IDENTITY"
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "App-specific password for notarization"
if xcrun notarytool history --keychain-profile "$PROFILE" >/dev/null 2>&1; then
  printf '  %s✓%s the notarization profile "%s" already works; skipping this and the next stage.\n' \
    "$GREEN" "$RESET" "$PROFILE"
  HAVE_PROFILE=1
else
  HAVE_PROFILE=0
  say "Apple's notary service needs an app-specific password, not your Apple ID password."
  open_url "https://account.apple.com/account/manage"
  step "Sign in, then open Sign-In and Security → App-Specific Passwords."
  step "Click + (Generate), name it \"Dahlia notarization\", and click Create."
  step "Keep that window open: you'll paste the password in the next stage. Don't paste it here."
fi
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Save the notarization profile"
if (( HAVE_PROFILE )); then
  note "Already saved."
else
  ask APPLE_ID "Your Apple ID email (the developer account):"
  say "notarytool will now ask for the app-specific password and save it in your keychain."
  note "Nothing is written to the repository."
  until xcrun notarytool store-credentials "$PROFILE" --apple-id "$APPLE_ID" --team-id "$TEAM_ID"; do
    warn "That didn't work. Check the Apple ID and paste the app-specific password again."
    confirm "Try again?" || { warn "Stopping. Re-run this script when ready."; exit 1; }
  done
  xcrun notarytool history --keychain-profile "$PROFILE" >/dev/null
  printf '  %s✓%s profile "%s" saved and accepted by Apple\n' "$GREEN" "$RESET" "$PROFILE"
fi
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Create the update-signing key"
say "Fetching Sparkle (pinned and checksum-verified)…"
SPARKLE=$(python3 scripts/prepare-sparkle.py | tail -n1)
KEYS="$SPARKLE/bin/generate_keys"
if PUBLIC_KEY=$("$KEYS" -p 2>/dev/null) && [[ -n "$PUBLIC_KEY" ]]; then
  note "Your keychain already has a Sparkle key; reusing it."
else
  say "Creating the key. Allow the keychain prompt if one appears."
  "$KEYS" >/dev/null
  PUBLIC_KEY=$("$KEYS" -p)
fi
PUBLIC_KEY=$(printf '%s' "$PUBLIC_KEY" | tr -d '[:space:]')
if ! printf '%s' "$PUBLIC_KEY" | grep -qE '^[A-Za-z0-9+/]{43}=$'; then
  warn "generate_keys printed something unexpected: $PUBLIC_KEY"
  exit 1
fi
current=$(grep -vE '^[[:space:]]*(#|$)' "$KEY_FILE" || true)
if [[ "$current" == "$PUBLIC_KEY" ]]; then
  note "$KEY_FILE already has this key."
elif [[ -n "$current" ]]; then
  warn "$KEY_FILE has a different key: $current"
  warn "Changing it would stop installed copies of Dahlia from accepting updates."
  confirm "Replace it with the key from this keychain anyway?" || exit 1
  grep -E '^[[:space:]]*#' "$KEY_FILE" > "$KEY_FILE.tmp"; printf '%s\n' "$PUBLIC_KEY" >> "$KEY_FILE.tmp"
  mv "$KEY_FILE.tmp" "$KEY_FILE"
else
  printf '%s\n' "$PUBLIC_KEY" >> "$KEY_FILE"
fi
printf '  %s✓%s public key: %s\n' "$GREEN" "$RESET" "$PUBLIC_KEY"
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Back up the private key"
warn "If this key is lost, no installed copy of Dahlia can ever accept an update again."
rm -f "$BACKUP"
"$KEYS" -x "$BACKUP"
chmod 600 "$BACKUP"
say "The private key is now in a file: $BACKUP"
step "Open it (e.g. open -e \"$BACKUP\") and copy its one line."
step "Save it in your password manager (the Passwords app, 1Password…) as \"Dahlia Sparkle private key\"."
step "To restore it on another Mac later: generate_keys -f FILE (see RELEASING.md)."
until confirm "Is it saved somewhere safe outside this Mac's keychain?"; do
  pause "Take your time. Press Enter when it's saved."
done
rm -P "$BACKUP" 2>/dev/null || rm -f "$BACKUP"
printf '  %s✓%s deleted %s\n' "$GREEN" "$RESET" "$BACKUP"
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Publish the public key"
if git diff --quiet -- "$KEY_FILE"; then
  note "$KEY_FILE is already committed."
else
  git --no-pager diff -- "$KEY_FILE"
  confirm "Commit this public key and push it to github.com/qoodeng/dahlia main?" \
    || { warn "Not pushed. Commit $KEY_FILE yourself before releasing."; exit 1; }
  git add "$KEY_FILE"
  git commit -q -m "Add the Sparkle update-signing public key"
  git push -q origin main
  printf '  %s✓%s pushed %s\n' "$GREEN" "$RESET" "$(git log --oneline -1)"
fi

finish
say "Next: write release notes in a file, then release:"
note "  export DAHLIA_NOTARY_PROFILE=$PROFILE"
note "  scripts/release.sh --dry-run"
note "  scripts/release.sh --notes notes.md"
printf '\n'
}

run_wizard "$@"; exit
